mapper.select:
SELECT 
FROM `model`
WHERE model_key = #{modelKey}
  AND capability = #{capability}
ORDER BY id ASC
LIMIT 1

SELECT 
FROM `model` WHERE model_key = #{modelKey} AND capability = #{capability}
ORDER BY id ASC LIMIT 1 FOR UPDATE

SELECT 
FROM `model`
WHERE enabled = 1
  AND model_key = #{modelKey}
  AND capability = #{capability}
ORDER BY sort ASC, id ASC

mapper.update:
UPDATE `model`
SET capability = #{capability}, cost_per_unit = NULL, cost_quota_type = NULL,
    cost_synced_at = NULL, updated_at = NOW()
WHERE id = #{model.id}
  AND capability = #{model.capability}
  AND upstream_model = #{model.upstreamModel}
  AND (model_key = #{model.modelKey,jdbcType=VARCHAR}
       OR (model_key IS NULL AND #{model.modelKey,jdbcType=VARCHAR} IS NULL))

