SELECT 
FROM `model`
WHERE channel_id = #{channelId}
  AND upstream_model = #{upstreamModel}
ORDER BY id ASC
LIMIT 1 FOR UPDATE

mapper.update:
UPDATE `model`
SET cost_per_unit = #{costPerUnit},
    cost_quota_type = #{costQuotaType},
    cost_synced_at = #{syncedAt}
