UPDATE `model`
SET cost_per_unit = #{costPerUnit},
    cost_quota_type = #{costQuotaType},
    cost_synced_at = #{syncedAt}
WHERE id = #{route.id}
  AND channel_id = #{route.channelId}
  AND upstream_model = #{route.upstreamModel}
  AND capability = #{route.capability}
